lines <- strsplit(.context$bslib_source, "\n")[[1]]
bs_def_idx <- grep("^bs_theme\s*<-", lines)
bs_def_idx

# if not found, search for 'bs_theme <- function' pattern
if (length(bs_def_idx) == 0) bs_def_idx <- grep("bs_theme\s*<-\s*function", lines)
bs_def_idx

# peek around the first definition
if (length(bs_def_idx) > 0) {
  i <- bs_def_idx[1]
  start <- max(1, i-40); end <- min(length(lines), i+200)
  cat(paste(lines[start:end], collapse = "\n"))
} else {
  cat('bs_theme definition not found')
}

# search for bootswatch occurrences
lines <- strsplit(.context$bslib_source, "\n")[[1]]
boots_idx <- grep("bootswatch", lines, ignore.case = TRUE)
length(boots_idx)
head(boots_idx, 40)
# show contexts around some occurrences
if (length(boots_idx)>0) {
  cat(paste(sapply(head(boots_idx, 12), function(i){
    start <- max(1, i-6); end <- min(length(lines), i+6);
    paste0('--- index: ', i, ' ---\n', paste(lines[start:end], collapse='\n'))
  }), collapse='\n\n'))
} else cat('no bootswatch found')

# search for 'navbar-light-bg' or 'navbar-dark-bg' which hint at brand mapping
nav_idx <- grep("navbar-light-bg|navbar-dark-bg|navbar-light|navbar-dark", lines)
head(nav_idx, 40)
if (length(nav_idx)>0) cat(paste(sapply(head(nav_idx,12), function(i){
  start<-max(1,i-6); end<-min(length(lines), i+6);
  paste0('--- index: ', i, ' ---\n', paste(lines[start:end], collapse='\n'))
}), collapse='\n\n'))

# search for functions that mention 'brand' in names or comments
brand_fn_idx <- grep("brand", lines, ignore.case = TRUE)
length(brand_fn_idx)
brand_fn_idx_head <- head(brand_fn_idx, 40)
if (length(brand_fn_idx_head)>0) cat(paste(sapply(brand_fn_idx_head, function(i){
  start<-max(1,i-3); end<-min(length(lines), i+3);
  paste0('--- index: ', i, ' ---\n', paste(lines[start:end], collapse='\n'))
}), collapse='\n\n') )

list(total_bootswatch_occurrences = length(boots_idx), total_brand_occurrences = length(brand_fn_idx))

